const bajo = $('Stock bajo mínimo').all()
  .map(item => item.json)
  .filter(r => r.nombre);

const atrasadas = $('OC atrasadas').all()
  .map(item => item.json)
  .filter(r => r.id_orden);

// Fecha de corte de los datos de la demostración.
const fecha = '2026-11-14';
const lineas = [];

for (const r of bajo) {
  const accion = Number(r.en_transito) > 0
    ? `Hay ${r.en_transito} ${r.unidad_base} en tránsito: revisar la orden pendiente antes de comprar.`
    : 'Revisar sugerencia de reposición y emitir orden de compra.';

  lineas.push(
    `${r.nombre}: stock ${r.stock} ${r.unidad_base}, mínimo ${r.minimo}. ${accion}`
  );
}

for (const r of atrasadas) {
  lineas.push(
    `OC ${r.id_orden}: ${r.proveedor}, ${r.insumo}, atraso de ${r.dias_atraso} día(s). Contactar al proveedor.`
  );
}

return [{
  json: {
    hay_alertas: lineas.length > 0,
    asunto: `[Bob's Coffee] Alerta de inventario — ${fecha}`,
    cuerpo: [
      `Revisión del inventario al ${fecha}`,
      '',
      ...lineas,
      '',
      'Demostración con datos sintéticos de Bob’s Coffee.'
    ].join('\n')
  }
}];
